function validateNode(node, path = 'tree') {
  if (node === null || typeof node !== 'object' || Array.isArray(node)) {
    throw new Error(`${path}: expected an object`);
  }
  const keys = Object.keys(node);
  for (const k of keys) {
    if (k !== 'value' && k !== 'children') {
      throw new Error(`${path}: unexpected field "${k}"`);
    }
  }
  if (!('value' in node)) {
    throw new Error(`${path}: missing required field "value"`);
  }
  const v = node.value;
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    throw new Error(`${path}.value: expected an integer`);
  }
  if ('children' in node) {
    const c = node.children;
    if (!Array.isArray(c)) {
      throw new Error(`${path}.children: expected an array`);
    }
    c.forEach((child, i) => validateNode(child, `${path}.children[${i}]`));
  }
}
